def average(numbers):
    total = 0
    for n in numbers:
        total = total + n
    return total / len(numbers)

print(average([4, 8, 6]))   # 6.0

def grade(score):
    if score < 0 or score > 100:
        raise ValueError("score out of range")   # guard clause
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    return "C or below"

print(grade(90), grade(89))   # A B

def clamp(value, low=0, high=100):
    """Return value limited to the range [low, high]."""
    return max(low, min(value, high))

print(clamp(150))                              # 100
print(clamp(-5, low=-10))                      # -5
print(sorted(["bb", "a", "ccc"], key=len))     # ['a', 'bb', 'ccc']

