#include <stdlib.h>

int main(void) {
    int on_stack = 7;                        /* lives in main's frame */
    int *on_heap = malloc(sizeof *on_heap);
    *on_heap = 42;                           /* lives until we free it */
    printf("%d %d\n", on_stack, *on_heap);
    free(on_heap);                           /* forget this and it leaks */
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 1, y = 2;
    swap(&x, &y);
    printf("%d %d\n", x, y);   /* 2 1 */
    return 0;
}

def read_port(text):
    try:
        port = int(text)
    except ValueError:
        raise ValueError(f"port must be a number, got {text!r}") from None
    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range: {port}")
    return port

with open("config.txt") as f:          # closed even if an error occurs
    print(read_port(f.readline().strip()))

def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def test_is_leap():
    assert is_leap(2024)
    assert not is_leap(1900)      # divisible by 100 but not by 400
    assert is_leap(2000)          # divisible by 400
    assert not is_leap(2023)

test_is_leap()
print("ok")
